159	    /**
160	     * Returns the stored E.164 {@code telephone} formatted for humans: the recognized country code
161	     * (with its leading {@code '+'}), a space, then the national digits grouped in threes from the
162	     * left and separated by spaces (for example {@code '+61412345678'} renders as
163	     * {@code '+61 412 345 678'}). The split into country code and national number reuses
164	     * {@link #countryCodeOf(String)}, the single definition of that split. Returns {@code null} when
165	     * the owner has no telephone, and returns the raw E.164 value unchanged when it carries no
166	     * recognized country code. This is the single definition of an owner's human-readable telephone.
167	     *
168	     * @return the human-formatted telephone, or {@code null} when the owner has no telephone
169	     */
170	    @Transient
171	    public String getTelephoneDisplay() {
172	        if (this.telephone == null) {
173	            return null;
174	        }
175	        String countryCode = countryCodeOf(this.telephone);
176	        if (countryCode == null) {
177	            return this.telephone;
178	        }
179	        String national = this.telephone.substring(1 + countryCode.length());
180	        StringBuilder display = new StringBuilder("+").append(countryCode);
181	        for (int i = 0; i < national.length(); i += 3) {
182	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
183	        }
184	        return display.toString();
185	    }
