566	    /**
567	     * Builds the customer code assigned to a newly created owner. The code is formatted as
568	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
569	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
570	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
571	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
572	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
573	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
574	     * identity scheme needs.
575	     *
576	     * @param owner the owner being created, whose fields the code is derived from
577	     * @return the formatted customer code
578	     */
579	    private String customerCodeFor(Owner owner) {
580	        String region = owner.getRegion();
581	        String regionCode = region != null ? region : "UNKNOWN";
582	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
583	        return deduplicateCustomerCode(regionCode + "-" + hash8);
584	    }
585	
586	    /**
587	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
588	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
589	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
590	     *
591	     * @param baseCode the customer code computed for the owner being created
592	     * @return the base code when it is already unique, otherwise the de-duplicated code
593	     */
594	    private String deduplicateCustomerCode(String baseCode) {
595	        Set<String> existing = this.clinicService.findAllOwners().stream()
596	            .map(Owner::getCustomerCode)
597	            .filter(Objects::nonNull)
598	            .collect(Collectors.toSet());
599	        if (!existing.contains(baseCode)) {
600	            return baseCode;
601	        }
602	        int n = 2;
603	        while (existing.contains(baseCode + "-" + n)) {
604	            n++;
605	        }
606	        return baseCode + "-" + n;
607	    }
