653	    /**
654	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
655	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
656	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
657	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
658	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
659	     * {@link java.util.Optional#empty()} is returned.
660	     *
661	     * @param owner the owner being created, already carrying its normalized telephone and postcode
662	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
663	     */
664	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
665	        if (owner.getPostcode() == null) {
666	            return java.util.Optional.empty();
667	        }
668	        return this.clinicService.findAllOwners().stream()
669	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
670	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
671	                && owner.getPostcode().equals(existing.getPostcode())
672	                && !owner.getTelephone().equals(existing.getTelephone()))
673	            .findFirst();
674	    }
