677	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
678	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
679	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
680	     * the names of every offending field, which the exception advice renders as a 400 response
681	     * with an {@code errors} array.
682	     *
683	     * @param ownerFieldsDto the submitted owner fields
684	     */
685	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
686	        List<String> missing = new ArrayList<>();
687	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
688	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
689	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
690	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
691	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
692	        if (!missing.isEmpty()) {
693	            throw new RequiredFieldsMissingException(missing);
