822	    /**
823	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
824	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
825	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
826	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
827	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
828	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
829	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
830	     * 400 response naming the {@code postcode} field.
831	     *
832	     * @param postcode the submitted postcode, or {@code null} when omitted
833	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
834	     */
835	    private void validatePostcode(String postcode, String city) {
836	        if (postcode == null) {
837	            return;
838	        }
839	        if (!postcode.matches("^[0-9]{4}$")) {
840	            throw new InvalidFieldsException(List.of("postcode"));
841	        }
842	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
843	        if (range != null) {
844	            int value = Integer.parseInt(postcode);
845	            if (value < range[0] || value > range[1]) {
846	                throw new InvalidFieldsException(List.of("postcode"));
847	            }
848	        }
849	    }
