851	    /**
852	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
853	     * identity is its derived identity key (see {@link #identityKey(String, String, String)}) — its
854	     * normalized {@code telephone}, canonical {@code email} and shared {@code householdId} joined by
855	     * {@code '|'} — so a new owner is a hard duplicate only when an existing, non-deleted owner
856	     * matches it on all three. Two owners that merely share a household (the same last name and
857	     * postcode) but differ in telephone or email are distinct owners and are not rejected here; such a
858	     * near-match is instead recorded as a soft {@code possibleDuplicate} (see
859	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
860	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
861	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
862	     * deliberate household member and bypasses this block. An owner without a postcode belongs to no
863	     * shared household and is never a duplicate here.
864	     *
865	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
866	     */
867	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
868	        if (sharesHousehold(ownerFieldsDto)) {
869	            return;
870	        }
871	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
872	        if (householdId == null) {
873	            return;
874	        }
875	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
876	        boolean taken = householdMembers(householdId).stream()
877	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
878	            .anyMatch(existing -> identityKey.equals(
879	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
880	        if (taken) {
881	            throw new DuplicateIdentityException(identityKey);
882	        }
883	    }
884	
885	    /**
886	     * Builds the identity key that decides whether two owners denote the same identity: their
887	     * normalized {@code telephone}, canonical {@code email} (see {@link #canonicalEmail(String)}) and
888	     * shared {@code householdId}, joined by {@code '|'}. This is the single definition of owner
889	     * identity used by {@link #rejectDuplicateIdentity(OwnerFieldsDto)}; two owners are the same
890	     * identity exactly when their keys are equal, so a value stored on an existing owner and the
891	     * fields submitted for a new owner can be compared for identity after both pass through here.
892	     *
893	     * @param telephone the owner's normalized telephone
894	     * @param email the owner's email, or {@code null} when none was supplied
895	     * @param householdId the owner's shared household identifier
896	     * @return the identity key
897	     */
898	    private String identityKey(String telephone, String email, String householdId) {
899	        return telephone + "|" + canonicalEmail(email) + "|" + householdId;
900	    }
901	
902	    /**
903	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
904	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
905	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
906	     * resolves to the same stable value automatically, without any explicit linking. An owner without
907	     * a postcode belongs to no shared household and is left without a household identifier.
908	     *
909	     * @param owner the newly created owner, mutated in place with its household identifier
910	     */
911	    private void assignHousehold(Owner owner) {
912	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
913	    }
914	
915	    /**
916	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
917	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
918	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
919	     * every rule that treats a declared household member differently from an independent owner.
920	     *
921	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
922	     * @return {@code true} when the request opted into sharing a household
923	     */
924	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
925	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
926	    }
927	
928	    /**
929	     * Derives the stable {@code householdId} shared by every owner in the household identified by
930	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
931	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
932	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
933	     * postcode — regardless of creation order or address — resolve to the same identifier
934	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
935	     * returned.
936	     *
937	     * @param lastName the household's last name
938	     * @param postcode the household's postcode, or {@code null} when the owner has none
939	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
940	     */
941	    private String householdIdFor(String lastName, String postcode) {
942	        if (postcode == null) {
943	            return null;
944	        }
945	        return shaHex(householdKey(lastName, postcode), 12);
946	    }
947	
948	    /**
949	     * Builds the canonical household key that identifies the household a {@code lastName} and
950	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
951	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
952	     * owner fields make up a household and how they are normalized;
953	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
954	     * owners in the same household resolve to the same key and therefore the same identifier.
955	     *
956	     * @param lastName the household's last name
957	     * @param postcode the household's postcode
958	     * @return the normalized household key
959	     */
960	    private String householdKey(String lastName, String postcode) {
961	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
962	    }
963	
964	    /**
965	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
966	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
967	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
968	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
969	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
970	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
971	     * an {@link IllegalStateException} is thrown.
972	     *
973	     * @param input the string to hash
974	     * @param hexChars the number of leading upper-case hex characters to return
975	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
976	     */
977	    private String shaHex(String input, int hexChars) {
978	        try {
979	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
980	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
981	            StringBuilder sb = new StringBuilder();
982	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
983	                sb.append(String.format("%02X", digest[i]));
984	            }
985	            return sb.substring(0, hexChars);
986	        }
987	        catch (java.security.NoSuchAlgorithmException e) {
988	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
989	        }
990	    }
991	
992	    /**
993	     * Returns the owners that belong to the household identified by the given {@code householdId},
994	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
995	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
996	     * filters them out itself. The owners are taken from the current set, so after a create the
997	     * result includes the newly persisted owner. An owner without a household (a {@code null}
998	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
999	     * definition of a household's members, shared by every rule that reasons about the owners
1000	     * sharing a household (the household-duplicate block and the household member count).
1001	     *
1002	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1003	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
1004	     */
1005	    private List<Owner> householdMembers(String householdId) {
1006	        if (householdId == null) {
1007	            return List.of();
1008	        }
1009	        return this.clinicService.findAllOwners().stream()
1010	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1011	            .collect(Collectors.toList());
1012	    }
1013	
1014	    /**
1015	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1016	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1017	     * is taken against the current set of owners, so after a create it reflects the household's size
1018	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1019	     * belongs to no shared household and yields {@code 0}.
1020	     *
1021	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1022	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1023	     */
1024	    private int countHouseholdMembers(String householdId) {
1025	        return householdMembers(householdId).size();
1026	    }
1027	
1028	    /**
1029	     * Stamps an owner with its household member count, the number of owners sharing its household
1030	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1031	     * household size (its membership factor and level) reads a populated count rather than the
1032	     * unstamped default. This is the single definition of hydrating an owner with its household
1033	     * member count, shared by the create and read paths that render an owner's derived values.
1034	     *
1035	     * @param owner the owner to stamp, mutated in place with its household member count
1036	     */
1037	    private void applyHouseholdMemberCount(Owner owner) {
1038	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1039	    }
1040	
1041	    /**
1042	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1043	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1044	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1045	     *
1046	     * @param value the value to collapse, or {@code null}
1047	     * @return the whitespace-collapsed value, never {@code null}
1048	     */
1049	    private String collapseWhitespace(String value) {
1050	        if (value == null) {
1051	            return "";
1052	        }
1053	        return value.trim().replaceAll("\\s+", " ");
1054	    }
1055	
1056	    /**
1057	     * Common street-type abbreviations expanded during address normalization, keyed by their
1058	     * upper-cased token.
1059	     */
1060	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1061	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1062	
1063	    /**
1064	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1065	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1066	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1067	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1068	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1069	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1070	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1071	     * everywhere an address is stored or compared.
1072	     *
1073	     * @param address the submitted address value, or {@code null}
1074	     * @return the normalized address, never {@code null}
1075	     */
1076	    private String normalizeAddress(String address) {
1077	        if (address == null) {
1078	            return "";
1079	        }
1080	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1081	        if (collapsed.isEmpty()) {
1082	            return "";
1083	        }
1084	        String[] tokens = collapsed.split(" ");
1085	        StringBuilder sb = new StringBuilder(collapsed.length());
1086	        for (int i = 0; i < tokens.length; i++) {
1087	            if (i > 0) {
1088	                sb.append(' ');
1089	            }
1090	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1091	        }
1092	        return sb.toString();
1093	    }
1094	}
